def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            shape = {(y - minr, x - minc) for y, x in cells}
            oh, ow = maxr - minr + 1, maxc - minc + 1

            # A bounded zero region inside the object's bounding box is a hole.
            exterior = set()
            todo = []
            for yy in range(oh):
                for xx in range(ow):
                    if (yy, xx) not in shape and (
                        yy == 0 or yy == oh - 1 or xx == 0 or xx == ow - 1
                    ):
                        exterior.add((yy, xx))
                        todo.append((yy, xx))
            while todo:
                yy, xx = todo.pop()
                for ny, nx in ((yy - 1, xx), (yy + 1, xx), (yy, xx - 1), (yy, xx + 1)):
                    if (0 <= ny < oh and 0 <= nx < ow and
                            (ny, nx) not in shape and (ny, nx) not in exterior):
                        exterior.add((ny, nx))
                        todo.append((ny, nx))
            has_hole = any(
                (yy, xx) not in shape and (yy, xx) not in exterior
                for yy in range(oh) for xx in range(ow)
            )

            objects.append({
                "top": minr, "left": minc, "height": oh, "width": ow,
                "shape": shape, "color": color, "hole": has_hole
            })

    output = [[0] * w for _ in range(h)]

    for hole_group, anchor in ((True, "top"), (False, "bottom")):
        group = [o for o in objects if o["hole"] == hole_group]
        group.sort(key=lambda o: o["top"])

        if anchor == "top":
            for i, obj in enumerate(group):
                y = 0
                for prev in group[:i]:
                    overlaps = not (
                        obj["left"] + obj["width"] <= prev["left"] or
                        prev["left"] + prev["width"] <= obj["left"]
                    )
                    if overlaps:
                        y = max(y, prev["new_top"] + prev["height"])
                obj["new_top"] = y
        else:
            for i in range(len(group) - 1, -1, -1):
                obj = group[i]
                y = h - obj["height"]
                for later in group[i + 1:]:
                    overlaps = not (
                        obj["left"] + obj["width"] <= later["left"] or
                        later["left"] + later["width"] <= obj["left"]
                    )
                    if overlaps:
                        y = min(y, later["new_top"] - obj["height"])
                obj["new_top"] = y

        for obj in group:
            for dy, dx in obj["shape"]:
                output[obj["new_top"] + dy][obj["left"] + dx] = obj["color"]

    return output
